<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateThemeVO;

trait TemplateThemeAttributeHolder
{
    protected TemplateThemeVO|string|null $theme = null;
    protected bool $themeAssigned = false;

    public function getThemeOrCurrent(?TemplateThemeVO $theme): ?TemplateThemeVO
    {
        return $this->themeAssigned ? ($this->theme === null ? null : TemplateThemeVO::from($this->theme)) : $theme;
    }
    public function themeTryBuildInitial(ConstraintFailList $error): ?TemplateThemeVO
    {
        return  TemplateThemeVO::tryFrom($this->themeAssigned ? $this->theme : null, $error);
    }
    public function theme(TemplateThemeVO|string|null $theme): static
    {
        $this->theme = $theme;
        $this->themeAssigned = true;
        return $this;
    }
    public function getTheme(): ?string
    {
        return $this->theme instanceof TemplateThemeVO ? $this->theme->value() : $this->theme;
    }
    public function isThemeAssigned(): bool
    {
        return $this->themeAssigned;
    }
    public function writeThemeTo(mixed $att): void
    {
        if ($this->themeAssigned) {
            $att->theme($this->theme);
        }
    }
    public function readThemeFrom(mixed $att): void
    {
        if ($att->isThemeAssigned()) {
            $theme = $att->getTheme();
            $this->theme($theme);
        }
    }
    public function unsetTheme(): static
    {
        $this->themeAssigned = false;
        return $this;
    }
    protected function withDefaultTheme(): void
    {
    }
    protected function withAssertedThemeRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->themeAssigned = $this->themeAssigned) {
            $value->theme = TemplateThemeVO::tryFrom($this->theme, $errorsList);
        }
    }
}
